class Solution {
    public int countPoints(String rings) {
        int[] masks = new int[10];
        for (int i = 0; i < rings.length(); i += 2) {
            char color = rings.charAt(i);
            int rod = rings.charAt(i + 1) - '0';
            int bit = color == 'R' ? 1 : color == 'G' ? 2 : 4;
            masks[rod] |= bit;
        }

        int complete = 0;
        for (int mask : masks) {
            if (mask == 7) {
                complete++;
            }
        }
        return complete;
    }
}

class Solution {
    public int countPoints(String rings) {
        boolean[][] seen = new boolean[10][3];
        for (int i = 0; i < rings.length(); i += 2) {
            int rod = rings.charAt(i + 1) - '0';
            int color = colorIndex(rings.charAt(i));
            seen[rod][color] = true;
        }

        int complete = 0;
        for (int rod = 0; rod < 10; rod++) {
            if (seen[rod][0] && seen[rod][1] && seen[rod][2]) {
                complete++;
            }
        }
        return complete;
    }

    private int colorIndex(char color) {
        if (color == 'R') {
            return 0;
        }
        if (color == 'G') {
            return 1;
        }
        return 2;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int countPoints(String rings) {
        Set<Integer> redRods = new HashSet<>();
        Set<Integer> greenRods = new HashSet<>();
        Set<Integer> blueRods = new HashSet<>();

        for (int i = 0; i < rings.length(); i += 2) {
            char color = rings.charAt(i);
            int rod = rings.charAt(i + 1) - '0';
            if (color == 'R') {
                redRods.add(rod);
            } else if (color == 'G') {
                greenRods.add(rod);
            } else {
                blueRods.add(rod);
            }
        }

        int complete = 0;
        for (int rod = 0; rod < 10; rod++) {
            if (redRods.contains(rod) && greenRods.contains(rod) && blueRods.contains(rod)) {
                complete++;
            }
        }
        return complete;
    }
}

class Solution {
    public int countPoints(String rings) {
        boolean[][] seen = new boolean[10][3];
        int[] distinctColors = new int[10];
        int complete = 0;

        for (int i = 0; i < rings.length(); i += 2) {
            int rod = rings.charAt(i + 1) - '0';
            int color = colorIndex(rings.charAt(i));
            if (!seen[rod][color]) {
                seen[rod][color] = true;
                distinctColors[rod]++;
                if (distinctColors[rod] == 3) {
                    complete++;
                }
            }
        }
        return complete;
    }

    private int colorIndex(char color) {
        if (color == 'R') {
            return 0;
        }
        if (color == 'G') {
            return 1;
        }
        return 2;
    }
}
